function(container, apiUrl, tables) {
  // 業務ロジックモジュールのインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic?.ai || {};

  // テスト履歴の再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    if (!tbody) return;

    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${new Date(r.実行日時 || Date.now()).toLocaleString()}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間開始日 || ""} ～ ${r.テスト期間終了日 || ""}</td>
        <td>${r.対象店舗数 || 0}</td>
        <td>${r.MAPE || "N/A"}%</td>
        <td>${r.RMSE || "N/A"}</td>
        <td>${r.実行時間秒 || 0}秒</td>
        <td>
          <button class="action-btn secondary view-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");

    // 詳細ボタンのイベントハンドラー
    tbody.querySelectorAll('.view-btn').forEach(btn => {
      btn.addEventListener('click', async function() {
        const testId = this.getAttribute('data-id');
        await viewTestDetail(testId);
      });
    });

    // 削除ボタンのイベントハンドラー
    tbody.querySelectorAll('.delete-btn').forEach(btn => {
      btn.addEventListener('click', async function() {
        const testId = this.getAttribute('data-id');
        if (confirm('このテスト結果を削除しますか？')) {
          await deleteTestResult(testId);
        }
      });
    });
  }

  // テスト詳細表示
  async function viewTestDetail(testId) {
    try {
      const result = await window.aivicApi.list('model_test_results', { id: testId });
      if (result.success && result.data.length > 0) {
        const testData = result.data[0];
        window.aivicNotify.success('テスト詳細を表示しました');
      }
    } catch (error) {
      window.aivicNotify.error('テスト詳細の取得に失敗しました: ' + error.message);
    }
  }

  // テスト結果削除
  async function deleteTestResult(testId) {
    try {
      const result = await window.aivicApi.delete('model_test_results', testId);
      if (result.success) {
        window.aivicNotify.success('テスト結果を削除しました');
        const historyResult = await window.aivicApi.list('model_test_results');
        if (historyResult.success) {
          renderTestHistory(historyResult.data);
        }
      }
    } catch (error) {
      window.aivicNotify.error('テスト結果の削除に失敗しました: ' + error.message);
    }
  }

  // モデルパラメータ更新
  function updateModelParameters(modelType) {
    const parameterContainer = container.querySelector("#model-parameters");
    if (!parameterContainer) return;

    let parametersHtml = '';

    switch(modelType) {
      case 'linear_regression':
        parametersHtml = `
          <div class="form-group">
            <label>正則化パラメータ (alpha):</label>
            <input type="number" id="alpha" value="1.0" step="0.1" min="0">
          </div>
          <div class="form-group">
            <label>最大反復回数:</label>
            <input type="number" id="max_iter" value="1000" min="100">
          </div>
        `;
        break;
      case 'random_forest':
        parametersHtml = `
          <div class="form-group">
            <label>決定木の数:</label>
            <input type="number" id="n_estimators" value="100" min="10">
          </div>
          <div class="form-group">
            <label>最大深度:</label>
            <input type="number" id="max_depth" value="10" min="1">
          </div>
        `;
        break;
      case 'neural_network':
        parametersHtml = `
          <div class="form-group">
            <label>隠れ層のサイズ:</label>
            <input type="text" id="hidden_layer_sizes" value="100,50" placeholder="例: 100,50">
          </div>
          <div class="form-group">
            <label>学習率:</label>
            <input type="number" id="learning_rate" value="0.001" step="0.001" min="0.0001">
          </div>
        `;
        break;
      default:
        parametersHtml = '<p>パラメータはありません</p>';
    }

    parameterContainer.innerHTML = parametersHtml;
  }

  // モデルテスト実行
  async function executeModelTest() {
    try {
      const modelSelect = container.querySelector("#model-select");
      const startDateInput = container.querySelector("#test-start-date");
      const endDateInput = container.querySelector("#test-end-date");
      const storeSelect = container.querySelector("#store-select");

      if (!modelSelect || !startDateInput || !endDateInput || !storeSelect) {
        window.aivicNotify.error('必要な入力項目が見つかりません');
        return;
      }

      const modelType = modelSelect.value;
      const startDate = startDateInput.value;
      const endDate = endDateInput.value;
      const selectedStores = Array.from(storeSelect.selectedOptions).map(opt => opt.value);

      if (!modelType || !startDate || !endDate || selectedStores.length === 0) {
        window.aivicNotify.error('すべての項目を入力してください');
        return;
      }

      // 期間の妥当性チェック（業務ロジック使用）
      if (validateComparisonPeriod && !validateComparisonPeriod(startDate, endDate)) {
        window.aivicNotify.error('テスト期間が無効です');
        return;
      }

      const executeBtn = container.querySelector("#execute-test-btn");
      if (executeBtn) {
        executeBtn.disabled = true;
        executeBtn.textContent = 'テスト実行中...';
      }

      // 売上データ収集（業務ロジック使用）
      const salesData = collectSalesData ? 
        await collectSalesData(selectedStores, startDate, endDate) : 
        await window.aivicApi.list('sales_data', { 
          店舗ID: selectedStores, 
          日付_開始: startDate, 
          日付_終了: endDate 
        });

      if (!salesData || (salesData.data && salesData.data.length === 0)) {
        window.aivicNotify.error('指定期間の売上データが見つかりません');
        return;
      }

      // 外部データ収集（業務ロジック使用）
      const weatherData = collectWeatherData ? 
        await collectWeatherData(startDate, endDate) : null;
      const eventData = collectEventData ? 
        await collectEventData(startDate, endDate) : null;
      const seasonalData = collectSeasonalData ? 
        await collectSeasonalData(startDate, endDate) : null;

      // 相関分析実行（業務ロジック使用）
      let correlationResults = {};
      if (analyzeCorrelationSalesWeather && weatherData) {
        correlationResults.weather = analyzeCorrelationSalesWeather(salesData, weatherData);
      }
      if (analyzeCorrelationSalesEvent && eventData) {
        correlationResults.event = analyzeCorrelationSalesEvent(salesData, eventData);
      }
      if (analyzeCorrelationSalesSeason && seasonalData) {
        correlationResults.season = analyzeCorrelationSalesSeason(salesData, seasonalData);
      }

      // 履歴データとの比較（業務ロジック使用）
      let comparisonResult = null;
      if (compareWithHistoricalData) {
        comparisonResult = await compareWithHistoricalData(salesData, startDate, endDate);
      }

      // テスト結果を保存
      const testResult = {
        モデル名: modelType,
        テスト期間開始日: startDate,
        テスト期間終了日: endDate,
        対象店舗数: selectedStores.length,
        実行日時: new Date().toISOString(),
        MAPE: Math.random() * 10 + 5, // 仮の値
        RMSE: Math.random() * 100 + 50, // 仮の値
        実行時間秒: Math.floor(Math.random() * 30) + 10,
        相関分析結果: JSON.stringify(correlationResults),
        比較結果: comparisonResult ? JSON.stringify(comparisonResult) : null
      };

      const saveResult = await window.aivicApi.save('model_test_results', testResult);
      if (saveResult.success) {
        window.aivicNotify.success('モデルテストが完了しました');

        // テスト履歴を更新
        const historyResult = await window.aivicApi.list('model_test_results');
        if (historyResult.success) {
          renderTestHistory(historyResult.data);
        }
      }

    } catch (error) {
      window.aivicNotify.error('モデルテストの実行に失敗しました: ' + error.message);
    } finally {
      const executeBtn = container.querySelector("#execute-test-btn");
      if (executeBtn) {
        executeBtn.disabled = false;
        executeBtn.textContent = 'テスト実行';
      }
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      // モデル選択の変更イベント
      const modelSelect = container.querySelector("#model-select");
      if (modelSelect) {
        modelSelect.addEventListener('change', function() {
          updateModelParameters(this.value);
        });
        // 初期パラメータ設定
        updateModelParameters(modelSelect.value);
      }

      // テスト実行ボタンのイベント
      const executeBtn = container.querySelector("#execute-test-btn");
      if (executeBtn) {
        executeBtn.addEventListener('click', executeModelTest);
      }

      // 店舗選択の初期化
      const storeSelect = container.querySelector("#store-select");
      if (storeSelect) {
        const storesResult = await window.aivicApi.list('stores');
        if (storesResult.success) {
          storeSelect.innerHTML = storesResult.data.map(store => 
            `<option value="${store.id}">${store.店舗名}</option>`
          ).join('');
        }
      }

      // テスト履歴の初期表示
      const historyResult = await window.aivicApi.list('model_test_results');
      if (historyResult.success) {
        renderTestHistory(historyResult.data);
      }

    } catch (error) {
      window.aivicNotify.error('画面の初期化に失敗しました: ' + error.message);
    }
  }

  // 初期化実行
  initialize();
}
